declare module '@ihui/ptc-runtime' {
  export type PtcJsonValue = any
  export type PtcBindingNamespace = {
    global: string
    functions: Record<string, (args: any) => any>
    [key: string]: any
  }
  export type PtcRunSpec = any
  export type PtcRunResult = any
  export type PtcRuntime = any

  export class NodePtcRuntime {
    constructor(options?: Record<string, unknown>)
    run(spec: PtcRunSpec): Promise<PtcRunResult>
    dispose?(): Promise<void> | void
  }

  export class NodeReplRuntime {
    constructor(options?: Record<string, unknown>)
    run(spec: PtcRunSpec): Promise<PtcRunResult>
    dispose?(): Promise<void> | void
  }

  export const PTC_MAX_BINDING_TIMEOUT_MS: number
  export const PTC_DEFAULT_BINDING_TIMEOUT_MS: number
}
